create table if not exists public.stories(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,image_url text not null,caption text not null default '' check(char_length(caption)<=180),audience text not null default 'everyone' check(audience in('everyone','connections')),created_at timestamptz not null default now(),expires_at timestamptz not null default(now()+interval '24 hours'));
create index if not exists stories_active_idx on public.stories(expires_at desc);
alter table public.stories enable row level security;
drop policy if exists stories_read_audience on public.stories;
create policy stories_read_audience on public.stories for select to authenticated using(expires_at>now() and (audience='everyone' or user_id=auth.uid() or exists(select 1 from public.connections c where(c.user_a=auth.uid() and c.user_b=stories.user_id)or(c.user_b=auth.uid() and c.user_a=stories.user_id))));
drop policy if exists stories_insert_own on public.stories;
create policy stories_insert_own on public.stories for insert to authenticated with check(user_id=auth.uid());
drop policy if exists stories_delete_own on public.stories;
create policy stories_delete_own on public.stories for delete to authenticated using(user_id=auth.uid());
create table if not exists public.notes(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,content text not null check(char_length(content) between 1 and 100),audience text not null default 'everyone' check(audience in('everyone','connections')),created_at timestamptz not null default now(),expires_at timestamptz not null default(now()+interval '24 hours'));
create index if not exists notes_active_idx on public.notes(expires_at desc);
alter table public.notes enable row level security;
drop policy if exists notes_read_audience on public.notes;
create policy notes_read_audience on public.notes for select to authenticated using(expires_at>now() and (audience='everyone' or user_id=auth.uid() or exists(select 1 from public.connections c where(c.user_a=auth.uid() and c.user_b=notes.user_id)or(c.user_b=auth.uid() and c.user_a=notes.user_id))));
drop policy if exists notes_insert_own on public.notes;
create policy notes_insert_own on public.notes for insert to authenticated with check(user_id=auth.uid());
drop policy if exists notes_delete_own on public.notes;
create policy notes_delete_own on public.notes for delete to authenticated using(user_id=auth.uid());
create table if not exists public.daily_prompts(id uuid primary key default gen_random_uuid(),prompt_date date not null unique default current_date,prompt text not null,created_at timestamptz not null default now());
create table if not exists public.prompt_responses(id uuid primary key default gen_random_uuid(),prompt_id uuid not null references public.daily_prompts(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,response text not null check(char_length(response) between 1 and 500),created_at timestamptz not null default now(),unique(prompt_id,user_id));
alter table public.daily_prompts enable row level security; alter table public.prompt_responses enable row level security;
drop policy if exists prompts_read_auth on public.daily_prompts; create policy prompts_read_auth on public.daily_prompts for select to authenticated using(true);
drop policy if exists prompt_responses_read_auth on public.prompt_responses; create policy prompt_responses_read_auth on public.prompt_responses for select to authenticated using(true);
drop policy if exists prompt_responses_insert_own on public.prompt_responses; create policy prompt_responses_insert_own on public.prompt_responses for insert to authenticated with check(user_id=auth.uid());
drop policy if exists prompt_responses_update_own on public.prompt_responses; create policy prompt_responses_update_own on public.prompt_responses for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());
insert into public.daily_prompts(prompt_date,prompt) values(current_date,'What is one thing you wish more people understood about you?'),(current_date+1,'What small moment made your day better recently?'),(current_date+2,'What are you learning to let go of?'),(current_date+3,'What does a genuinely good friendship feel like?'),(current_date+4,'What is a goal you are quietly working toward?'),(current_date+5,'What belief have you changed your mind about?'),(current_date+6,'What experience would you love to share with a friend?') on conflict(prompt_date) do nothing;
create table if not exists public.blends(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,name text not null check(char_length(name) between 3 and 60),description text not null default '' check(char_length(description)<=240),created_at timestamptz not null default now());
create table if not exists public.blend_members(blend_id uuid not null references public.blends(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,joined_at timestamptz not null default now(),primary key(blend_id,user_id));
create table if not exists public.blend_items(id uuid primary key default gen_random_uuid(),blend_id uuid not null references public.blends(id) on delete cascade,user_id uuid not null references public.profiles(id) on delete cascade,content text not null check(char_length(content) between 1 and 500),created_at timestamptz not null default now());
alter table public.blends enable row level security; alter table public.blend_members enable row level security; alter table public.blend_items enable row level security;
drop policy if exists blends_read_auth on public.blends; create policy blends_read_auth on public.blends for select to authenticated using(true);
drop policy if exists blends_insert_owner on public.blends; create policy blends_insert_owner on public.blends for insert to authenticated with check(owner_id=auth.uid());
drop policy if exists blend_members_read on public.blend_members; create policy blend_members_read on public.blend_members for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.blend_members mine where mine.blend_id=blend_members.blend_id and mine.user_id=auth.uid()));
drop policy if exists blend_members_insert_self on public.blend_members; create policy blend_members_insert_self on public.blend_members for insert to authenticated with check(user_id=auth.uid());
drop policy if exists blend_items_read_members on public.blend_items; create policy blend_items_read_members on public.blend_items for select to authenticated using(exists(select 1 from public.blend_members bm where bm.blend_id=blend_items.blend_id and bm.user_id=auth.uid()));
drop policy if exists blend_items_insert_members on public.blend_items; create policy blend_items_insert_members on public.blend_items for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.blend_members bm where bm.blend_id=blend_items.blend_id and bm.user_id=auth.uid()));
create or replace function public.create_connect_blend(p_name text,p_description text default '') returns uuid language plpgsql security definer set search_path=public as $$ declare new_id uuid; begin if auth.uid() is null then raise exception 'Sign in first'; end if; if char_length(trim(p_name))<3 then raise exception 'Blend name is too short'; end if; insert into public.blends(owner_id,name,description) values(auth.uid(),left(trim(p_name),60),left(trim(coalesce(p_description,'')),240)) returning id into new_id; insert into public.blend_members(blend_id,user_id) values(new_id,auth.uid()); return new_id; end $$;
